sop:
@n1 syntax.nominal head="120"
@c1 syntax.clause form=imperative verb="add" discourse="please" complement=$n1 complement=$n2
@n2 syntax.nominal dependent="a" head="person"

alt:
@n1 syntax.nominal head="120"
@c1 syntax.clause form=imperative verb="add" discourse="please" complement=$n2
@n2 syntax.nominal dependent="a" head="person"
@c2 syntax.clause form=fragment complement=$n1
@r1 syntax.relation from=$c1 to=$c2
